targets.query:
// Age of the newest sample, in seconds. Deliberately the same signal as the
// provisioned "AlphaESS collector data stale" alert (and the same 300s
// threshold), so this panel and the alert can never disagree.
//
// Data staleness rather than the collector_health events, because an outage
// is "no data is arriving", whatever the cause: a failing poll loop writes
// failure events, but a dead container, a wrong bucket or a broken datasource
// write nothing at all -- and those must show red too, not a stale "ALL OK".
//
// Fixed -1h lookback, not the time picker: the question is "right now", which
// must not change when the dashboard is set to 7d.
from(bucket: "alphaess")
  |> range(start: -1h)
  |> filter(fn: (r) => r._measurement == "power_readings" and r._field == "soc_percent")
  |> last()
  |> map(fn: (r) => ({_time: r._time, _value: float(v: int(v: now()) - int(v: r._time)) / 1000000000.0}))
  |> keep(columns: ["_time", "_value"])
  |> yield(name: "data_age")

// Fixed long lookback, not the time picker: "no failure in the selected
// range" would otherwise read as a suspiciously large uptime.
from(bucket: "alphaess")
  |> range(start: -90d)
  |> filter(fn: (r) => r._measurement == "collector_health" and r.event == "failure" and r._field == "failures")
  |> group()
  |> last()
  |> map(fn: (r) => ({_time: r._time, _value: float(v: int(v: now()) - int(v: r._time)) / 1000000000.0}))
  |> yield(name: "since_last_failure")

import "date"
import "timezone"

option location = timezone.location(name: "Europe/Amsterdam")

// Same accounting as pricing.compute_day() / efficiency.coverage_of(): cadence
// drift and the odd skipped poll never count as missing, only gaps beyond 3x
// the poll interval (charged at gap - pollIntervalS each), plus any unsampled
// head/tail of the day.
//
// Every conditional below is written on a single physical line, and every
// intermediate value is its own `map()` stage rather than a local variable --
// Grafana's bundled Flux parser errors on multi-line if/then/else and on
// block-bodied functions with local `x = ...` assignments (confirmed against
// the live instance; both are otherwise-valid Flux, just not accepted here).
pollIntervalS = 30.0
gapThresholdS = 90.0

samples = from(bucket: "alphaess")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "power_readings" and r._field == "soc_percent")
  |> group()
  |> sort(columns: ["_time"])

// One row per Amsterdam calendar day (DST-aware, via option location). For
// each day: first/last sample time, the largest inter-sample gap, how many
// gaps exceeded gapThresholdS, and the total charged "outage" seconds. The
// gap since the previous sample is recomputed inline wherever it is needed --
// a record literal's fields cannot see each other, so there is no way to name
// it once.
daily = samples
  |> aggregateWindow(
      every: 1d,
      timeSrc: "_start",
      createEmpty: false,
      fn: (tables=<-, column) => tables
        |> sort(columns: ["_time"])
        |> reduce(
            identity: {count: 0, first_time: time(v: 0), last_time: time(v: 0), prev_time: time(v: 0), max_gap: 0.0, gap_count: 0, outage: 0.0},
            fn: (r, accumulator) => ({count: accumulator.count + 1, first_time: (if accumulator.count == 0 then r._time else accumulator.first_time), last_time: r._time, prev_time: r._time, max_gap: (if accumulator.count == 0 then accumulator.max_gap else if (float(v: int(v: r._time) - int(v: accumulator.prev_time)) / 1000000000.0) > accumulator.max_gap then (float(v: int(v: r._time) - int(v: accumulator.prev_time)) / 1000000000.0) else accumulator.max_gap), gap_count: accumulator.gap_count + (if accumulator.count > 0 and (float(v: int(v: r._time) - int(v: accumulator.prev_time)) / 1000000000.0) > gapThresholdS then 1 else 0), outage: accumulator.outage + (if accumulator.count > 0 and (float(v: int(v: r._time) - int(v: accumulator.prev_time)) / 1000000000.0) > gapThresholdS then (float(v: int(v: r._time) - int(v: accumulator.prev_time)) / 1000000000.0) - pollIntervalS else 0.0)})
        )
    )

// Coverage denominator: the day's own [local midnight, next local midnight)
// clipped to the selected time range and to now(). An in-progress day (or a
// day the picker only partly covers) is judged on its elapsed portion, not a
// fixed 24h. For a fully-contained past day this reduces to the plain day
// length (23h/25h on a DST-transition day). Built as a chain of single-field
// `map()` stages -- each one references only fields an earlier stage already
// added -- rather than local variables, for the parser reason noted above.
result = daily
  |> map(fn: (r) => ({r with day_end: date.add(d: 1d, to: r._time)}))
  |> map(fn: (r) => ({r with range_start: (if r._time > v.timeRangeStart then r._time else v.timeRangeStart)}))
  |> map(fn: (r) => ({r with range_end_a: (if r.day_end < v.timeRangeStop then r.day_end else v.timeRangeStop)}))
  |> map(fn: (r) => ({r with range_end: (if r.range_end_a < now() then r.range_end_a else now())}))
  |> map(fn: (r) => ({r with day_len_s: float(v: int(v: r.range_end) - int(v: r.range_start)) / 1000000000.0}))
  |> map(fn: (r) => ({r with head_s: (if r.first_time > r.range_start then float(v: int(v: r.first_time) - int(v: r.range_start)) / 1000000000.0 else 0.0)}))
  |> map(fn: (r) => ({r with tail_s: (if r.range_end > r.last_time then float(v: int(v: r.range_end) - int(v: r.last_time)) / 1000000000.0 else 0.0)}))
  |> map(fn: (r) => ({r with raw_coverage_pct: (if r.day_len_s > 0.0 then (1.0 - (r.head_s + r.tail_s + r.outage) / r.day_len_s) * 100.0 else 0.0)}))
  |> map(fn: (r) => ({r with coverage_pct: (if r.raw_coverage_pct > 0.0 then r.raw_coverage_pct else 0.0)}))
  |> rename(columns: {max_gap: "max_gap_s"})
  |> sort(columns: ["_time"], desc: true)
  |> keep(columns: ["_time", "coverage_pct", "max_gap_s", "gap_count"])
  |> yield(name: "coverage_by_day")
